# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.errors import ProjectError
from rosterkit.models import Student


def make_student(last, first, section, email):
    return Student("id", last, first, section, email)


class ContactRowsTests(unittest.TestCase):
    def test_rows_are_sorted_and_aligned(self):
        rows = contact_rows([
            make_student("Zed", "Al", "B", "al@x.org"),
            make_student("Ames", "Beth", "A", "b@x.org")
        ])
        self.assertEqual(rows, [
            "Ames, Beth  A  b@x.org",
            "Zed, Al     B  al@x.org"
        ])

    def test_missing_email_names_the_student(self):
        nomail = make_student("Ames", "Beth", "A", None)
        with self.assertRaises(ProjectError) as caught:
            contact_rows([nomail])
        self.assertIn("Ames, Beth", str(caught.exception))

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])
